<?php
namespace App\Http\Controllers;
use App\Models\MaintenanceRequest; use App\Models\Tenant; use Illuminate\Http\Request;
class TenantPortalController extends Controller { public function show(string $token) { $tenant = Tenant::withoutGlobalScopes()->where('portal_token', $token)->with(['currentLease.unit.property', 'maintenanceRequests.property', 'maintenanceRequests.unit'])->firstOrFail(); return view('tenant-portal.show', compact('tenant')); } public function storeMaintenance(Request $request, string $token) { $tenant = Tenant::withoutGlobalScopes()->where('portal_token', $token)->with('currentLease.unit.property')->firstOrFail(); $lease = $tenant->currentLease; abort_unless($lease, 422, 'There is no active lease for this portal.'); $data = $request->validate(['title'=>['required','string','max:150'], 'description'=>['nullable','string','max:2000'], 'priority'=>['required','in:Low,Normal,High,Emergency']]); MaintenanceRequest::create($data + ['organization_id'=>$tenant->organization_id,'property_id'=>$lease->unit->property_id,'unit_id'=>$lease->unit_id,'tenant_id'=>$tenant->id,'reported_by'=>'Tenant','category'=>'Tenant report']); return back()->with('success', 'Your maintenance request has been sent to the property team.'); } }
